insert into proyecto (programa_id, nombre, tipo, objetivo, meta, indicador, resultado_2030) values (97, 'Espacios en la ciudad donde se enseñan oficios, técnicas ancestrales, producción agroecológica, cocina rural y cultura originaria. Fomentan el orgullo rural y el aprendizaje mutuo.', 'general', NULL, NULL, NULL, NULL);
